select public.upsert_bank_question($json${"id":"apos-easy-001","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":1,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Quando Jesus subiu ao céu, o que o escondeu dos olhos dos discípulos?","bible_ref":"Atos 1:9","verse_text":"E tendo ele dito estas coisas, enquanto eles o viam, ele foi levantado acima, e uma nuvem o tirou dos olhos deles."},"fr":{"prompt":"Quand Jésus fut élevé au ciel, qu’est-ce qui le cacha aux yeux des disciples ?","bible_ref":"Actes 1:9","verse_text":"Après avoir dit cela, il fut élevé pendant qu’ils le regardaient, et une nuée le déroba à leurs yeux."},"en":{"prompt":"When Jesus was taken up, what received him out of the disciples’ sight?","bible_ref":"Acts 1:9","verse_text":"And when he had spoken these things, while they beheld, he was taken up; and a cloud received him out of their sight."},"es":{"prompt":"Cuando Jesús fue alzado al cielo, ¿qué lo ocultó de los ojos de los discípulos?","bible_ref":"Hechos 1:9","verse_text":"Y habiendo dicho estas cosas, viéndolo ellos, fué alzado; y una nube le recibió y le quitó de sus ojos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma nuvem"},"fr":{"text":"Une nuée"},"en":{"text":"A cloud"},"es":{"text":"Una nube"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um carro de fogo"},"fr":{"text":"Un char de feu"},"en":{"text":"A chariot of fire"},"es":{"text":"Un carro de fuego"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma tempestade"},"fr":{"text":"Une tempête"},"en":{"text":"A storm"},"es":{"text":"Una tempestad"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Fumo"},"fr":{"text":"De la fumée"},"en":{"text":"Smoke"},"es":{"text":"Humo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-002","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":2,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"No dia de Pentecostes, o que apareceu sobre cada um dos discípulos?","bible_ref":"Atos 2:3","verse_text":"E foram vistas por eles línguas repartidas como que de fogo, e se pôs sobre cada um deles."},"fr":{"prompt":"Le jour de la Pentecôte, qu’est-ce qui apparut et se posa sur chacun des disciples ?","bible_ref":"Actes 2:3","verse_text":"Des langues, semblables à des langues de feu, leur apparurent, séparées les unes des autres, et se posèrent sur chacun d’eux."},"en":{"prompt":"On the day of Pentecost, what appeared and sat upon each of the disciples?","bible_ref":"Acts 2:3","verse_text":"And there appeared unto them cloven tongues like as of fire, and it sat upon each of them."},"es":{"prompt":"El día de Pentecostés, ¿qué apareció y se posó sobre cada uno de los discípulos?","bible_ref":"Hechos 2:3","verse_text":"Y se les aparecieron lenguas repartidas, como de fuego, que se asentó sobre cada uno de ellos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Línguas como de fogo"},"fr":{"text":"Des langues de feu"},"en":{"text":"Tongues like as of fire"},"es":{"text":"Lenguas como de fuego"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma pomba"},"fr":{"text":"Une colombe"},"en":{"text":"A dove"},"es":{"text":"Una paloma"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Estrelas"},"fr":{"text":"Des étoiles"},"en":{"text":"Stars"},"es":{"text":"Estrellas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um arco-íris"},"fr":{"text":"Un arc-en-ciel"},"en":{"text":"A rainbow"},"es":{"text":"Un arco iris"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-003","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":3,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"O que disse Pedro ao coxo que não tinha para lhe dar?","bible_ref":"Atos 3:6","verse_text":"E Pedro disse: Prata e ouro eu não tenho; mas o que eu tenho, isso eu te dou: no nome de Jesus Cristo, o nazareno, levanta-te, e anda!"},"fr":{"prompt":"Qu’est-ce que Pierre dit au boiteux qu’il n’avait pas ?","bible_ref":"Actes 3:6","verse_text":"Alors Pierre lui dit: Je n’ai ni argent, ni or; mais ce que j’ai, je te le donne: au nom de Jésus-Christ de Nazareth, lève-toi et marche."},"en":{"prompt":"What did Peter tell the lame man he did not have?","bible_ref":"Acts 3:6","verse_text":"Then Peter said, Silver and gold have I none; but such as I have give I thee: In the name of Jesus Christ of Nazareth rise up and walk."},"es":{"prompt":"¿Qué le dijo Pedro al cojo que no tenía?","bible_ref":"Hechos 3:6","verse_text":"Y Pedro dijo: Ni tengo plata ni oro; mas lo que tengo te doy: en el nombre de Jesucristo de Nazaret, levántate y anda."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Prata e ouro"},"fr":{"text":"Argent et or"},"en":{"text":"Silver and gold"},"es":{"text":"Plata y oro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pão e peixe"},"fr":{"text":"Pain et poisson"},"en":{"text":"Bread and fish"},"es":{"text":"Pan y pescado"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Água e vinho"},"fr":{"text":"Eau et vin"},"en":{"text":"Water and wine"},"es":{"text":"Agua y vino"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Roupa e sandálias"},"fr":{"text":"Vêtements et sandales"},"en":{"text":"Clothes and sandals"},"es":{"text":"Ropa y sandalias"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-004","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":7,"verse_start":59,"verse_end":59,"texts":{"pt":{"prompt":"Como mataram Estêvão?","bible_ref":"Atos 7:59","verse_text":"E apedrejaram a Estêvão, que estava clamando e dizendo: Senhor Jesus, recebe o meu espírito."},"fr":{"prompt":"Comment Étienne fut-il mis à mort ?","bible_ref":"Actes 7:59","verse_text":"Et ils lapidaient Étienne, qui priait et disait: Seigneur Jésus, reçois mon esprit!"},"en":{"prompt":"How was Stephen put to death?","bible_ref":"Acts 7:59","verse_text":"And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit."},"es":{"prompt":"¿Cómo mataron a Esteban?","bible_ref":"Hechos 7:59","verse_text":"Y apedrearon á Esteban, invocando él y diciendo: Señor Jesús, recibe mi espíritu."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com pedras"},"fr":{"text":"Avec des pierres"},"en":{"text":"With stones"},"es":{"text":"Con piedras"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com setas"},"fr":{"text":"Avec des flèches"},"en":{"text":"With arrows"},"es":{"text":"Con flechas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com lanças"},"fr":{"text":"Avec des lances"},"en":{"text":"With spears"},"es":{"text":"Con lanzas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Com espadas"},"fr":{"text":"Avec des épées"},"en":{"text":"With swords"},"es":{"text":"Con espadas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-005","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":9,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Saulo viu uma luz do céu quando estava perto de que cidade?","bible_ref":"Atos 9:3","verse_text":"E indo, aconteceu que chegando perto de Damasco, repentinamente brilhou ao redor dele uma luz do céu."},"fr":{"prompt":"Saul vit une lumière du ciel alors qu’il approchait de quelle ville ?","bible_ref":"Actes 9:3","verse_text":"Comme il était en chemin, et qu’il approchait de Damas, tout à coup une lumière venant du ciel resplendit autour de lui."},"en":{"prompt":"Saul saw a light from heaven as he came near which city?","bible_ref":"Acts 9:3","verse_text":"And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven:"},"es":{"prompt":"¿Cerca de qué ciudad estaba Saulo cuando vio una luz del cielo?","bible_ref":"Hechos 9:3","verse_text":"Y yendo por el camino, aconteció que llegando cerca de Damasco, súbitamente le cercó un resplandor de luz del cielo;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Damasco"},"fr":{"text":"Damas"},"en":{"text":"Damascus"},"es":{"text":"Damasco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jerusalém"},"fr":{"text":"Jérusalem"},"en":{"text":"Jerusalem"},"es":{"text":"Jerusalem"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Roma"},"fr":{"text":"Rome"},"en":{"text":"Rome"},"es":{"text":"Roma"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jericó"},"fr":{"text":"Jéricho"},"en":{"text":"Jericho"},"es":{"text":"Jericó"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-006","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":9,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"No caminho, quem disse a Saulo: «Eu sou aquele a quem tu persegues»?","bible_ref":"Atos 9:5","verse_text":"E ele disse: Quem és, Senhor? E o Senhor disse: Eu sou Jesus, a quem tu persegues; duro é para ti dar coices contra os aguilhões."},"fr":{"prompt":"Sur le chemin, qui dit à Saul : « Je suis celui que tu persécutes » ?","bible_ref":"Actes 9:5","verse_text":"Il répondit: Qui es-tu, Seigneur? Et le Seigneur dit: Je suis Jésus que tu persécutes. Il te serait dur de regimber contre les aiguillons."},"en":{"prompt":"On the road, who said to Saul: “I am he whom thou persecutest”?","bible_ref":"Acts 9:5","verse_text":"And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks."},"es":{"prompt":"En el camino, ¿quién dijo a Saulo: «Yo soy aquel a quien tú persigues»?","bible_ref":"Hechos 9:5","verse_text":"Y él dijo: ¿Quién eres, Señor? Y él dijo: Yo soy Jesús á quien tú persigues: dura cosa te es dar coces contra el aguijón."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Jesus"},"fr":{"text":"Jésus"},"en":{"text":"Jesus"},"es":{"text":"Jesús"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pedro"},"fr":{"text":"Pierre"},"en":{"text":"Peter"},"es":{"text":"Pedro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Estêvão"},"fr":{"text":"Étienne"},"en":{"text":"Stephen"},"es":{"text":"Esteban"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-007","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":12,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Quem acordou Pedro na prisão e fez cair as correntes das suas mãos?","bible_ref":"Atos 12:7","verse_text":"E eis que veio acima um anjo do Senhor, e uma luz brilhou na prisão; e tocando em Pedro em sua lateral, despertou-o, dizendo; Levanta-te, depressa! E as correntes caíram de suas mãos."},"fr":{"prompt":"Qui réveilla Pierre dans la prison et fit tomber les chaînes de ses mains ?","bible_ref":"Actes 12:7","verse_text":"Et voici, un ange du Seigneur survint, et une lumière brilla dans la prison. L’ange réveilla Pierre, en le frappant au côté, et en disant: Lève-toi promptement! Les chaînes tombèrent de ses mains."},"en":{"prompt":"Who woke Peter in the prison, and made the chains fall off his hands?","bible_ref":"Acts 12:7","verse_text":"And, behold, the angel of the Lord came upon him, and a light shined in the prison: and he smote Peter on the side, and raised him up, saying, Arise up quickly. And his chains fell off from his hands."},"es":{"prompt":"¿Quién despertó a Pedro en la cárcel e hizo caer las cadenas de sus manos?","bible_ref":"Hechos 12:7","verse_text":"Y he aquí, el ángel del Señor sobrevino, y una luz resplandeció en la cárcel; é hiriendo á Pedro en el lado, le despertó, diciendo: Levántate prestamente. Y las cadenas se le cayeron de las manos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um anjo do Senhor"},"fr":{"text":"Un ange du Seigneur"},"en":{"text":"The angel of the Lord"},"es":{"text":"El ángel del Señor"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um soldado"},"fr":{"text":"Un soldat"},"en":{"text":"A soldier"},"es":{"text":"Un soldado"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O carcereiro"},"fr":{"text":"Le geôlier"},"en":{"text":"The jailer"},"es":{"text":"El carcelero"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Paulo"},"fr":{"text":"Paul"},"en":{"text":"Paul"},"es":{"text":"Pablo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-008","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":16,"verse_start":25,"verse_end":25,"texts":{"pt":{"prompt":"À meia-noite, na prisão, quem cantava hinos a Deus com Paulo?","bible_ref":"Atos 16:25","verse_text":"E perto da meia-noite, Paulo e Silas estavam orando, e cantando hinos a Deus; e os outros presos os escutavam."},"fr":{"prompt":"Vers minuit, dans la prison, qui chantait les louanges de Dieu avec Paul ?","bible_ref":"Actes 16:25","verse_text":"Vers le milieu de la nuit, Paul et Silas priaient et chantaient les louanges de Dieu, et les prisonniers les entendaient."},"en":{"prompt":"At midnight in the prison, who sang praises unto God with Paul?","bible_ref":"Acts 16:25","verse_text":"And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them."},"es":{"prompt":"A medianoche, en la cárcel, ¿quién cantaba himnos a Dios con Pablo?","bible_ref":"Hechos 16:25","verse_text":"Mas á media noche, orando Pablo y Silas, cantaban himnos á Dios: y los que estaban presos los oían."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Silas"},"fr":{"text":"Silas"},"en":{"text":"Silas"},"es":{"text":"Silas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pedro"},"fr":{"text":"Pierre"},"en":{"text":"Peter"},"es":{"text":"Pedro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Timóteo"},"fr":{"text":"Timothée"},"en":{"text":"Timothy"},"es":{"text":"Timoteo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Lucas"},"fr":{"text":"Luc"},"en":{"text":"Luke"},"es":{"text":"Lucas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-009","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":28,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Quando Paulo pôs lenha no fogo, que animal saiu e se agarrou à sua mão?","bible_ref":"Atos 28:3","verse_text":"E tendo Paulo recolhido uma quantidade de gravetos, e pondo-os no fogo, saiu uma víbora do calor, e fixou os dentes na mão dele."},"fr":{"prompt":"Quand Paul mit du bois au feu, quel animal en sortit et s’attacha à sa main ?","bible_ref":"Actes 28:3","verse_text":"Paul ayant ramassé un tas de broussailles et l’ayant mis au feu, une vipère en sortit par l’effet de la chaleur et s’attacha à sa main."},"en":{"prompt":"When Paul laid sticks on the fire, what animal came out and fastened on his hand?","bible_ref":"Acts 28:3","verse_text":"And when Paul had gathered a bundle of sticks, and laid them on the fire, there came a viper out of the heat, and fastened on his hand."},"es":{"prompt":"Cuando Pablo puso leña en el fuego, ¿qué animal salió y le acometió la mano?","bible_ref":"Hechos 28:3","verse_text":"Entonces habiendo Pablo recogido algunos sarmientos, y puéstolos en el fuego, una víbora, huyendo del calor, le acometió á la mano."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma víbora"},"fr":{"text":"Une vipère"},"en":{"text":"A viper"},"es":{"text":"Una víbora"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um escorpião"},"fr":{"text":"Un scorpion"},"en":{"text":"A scorpion"},"es":{"text":"Un escorpión"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma aranha"},"fr":{"text":"Une araignée"},"en":{"text":"A spider"},"es":{"text":"Una araña"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um rato"},"fr":{"text":"Un rat"},"en":{"text":"A rat"},"es":{"text":"Una rata"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-010","type":"choice","level":"easy","testament":"nt","book":"EPH","chapter":6,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Para estar firme contra as ciladas do diabo, o que devemos vestir?","bible_ref":"Efésios 6:11","verse_text":"Revesti-vos de toda a armadura de Deus, para que possais estar firmes contra as ciladas do diabo."},"fr":{"prompt":"Pour tenir ferme contre les ruses du diable, de quoi faut-il se revêtir ?","bible_ref":"Éphésiens 6:11","verse_text":"Revêtez-vous de toutes les armes de Dieu, afin de pouvoir tenir ferme contre les ruses du diable."},"en":{"prompt":"To stand against the wiles of the devil, what should we put on?","bible_ref":"Ephesians 6:11","verse_text":"Put on the whole armour of God, that ye may be able to stand against the wiles of the devil."},"es":{"prompt":"Para estar firmes contra las asechanzas del diablo, ¿de qué debemos vestirnos?","bible_ref":"Efesios 6:11","verse_text":"Vestíos de toda la armadura de Dios, para que podáis estar firmes contra las asechanzas del diablo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A armadura de Deus"},"fr":{"text":"Les armes de Dieu"},"en":{"text":"The whole armour of God"},"es":{"text":"La armadura de Dios"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma coroa de ouro"},"fr":{"text":"Une couronne d’or"},"en":{"text":"A golden crown"},"es":{"text":"Una corona de oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Roupas de rei"},"fr":{"text":"Des habits de roi"},"en":{"text":"Royal robes"},"es":{"text":"Ropas de rey"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um manto branco"},"fr":{"text":"Un manteau blanc"},"en":{"text":"A white cloak"},"es":{"text":"Un manto blanco"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-011","type":"choice","level":"easy","testament":"nt","book":"ACT","chapter":8,"verse_start":30,"verse_end":30,"texts":{"pt":{"prompt":"O que estava a ler o etíope quando Filipe correu para ele?","bible_ref":"Atos 8:30","verse_text":"E Filipe, correndo, ouviu que ele estava lendo ao profeta Isaías, e disse: Tu entendes o que estás lendo?"},"fr":{"prompt":"Que lisait l’Éthiopien quand Philippe accourut ?","bible_ref":"Actes 8:30","verse_text":"Philippe accourut, et entendit l’Éthiopien qui lisait le prophète Ésaïe. Il lui dit: Comprends-tu ce que tu lis?"},"en":{"prompt":"What was the Ethiopian reading when Philip ran to him?","bible_ref":"Acts 8:30","verse_text":"And Philip ran thither to him, and heard him read the prophet Esaias, and said, Understandest thou what thou readest?"},"es":{"prompt":"¿Qué leía el etíope cuando Felipe acudió a él?","bible_ref":"Hechos 8:30","verse_text":"Y acudiendo Felipe, le oyó que leía el profeta Isaías, y dijo: Mas ¿entiendes lo que lees?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O profeta Isaías"},"fr":{"text":"Le prophète Ésaïe"},"en":{"text":"The prophet Esaias"},"es":{"text":"El profeta Isaías"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O profeta Jonas"},"fr":{"text":"Le prophète Jonas"},"en":{"text":"The prophet Jonas"},"es":{"text":"El profeta Jonás"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O profeta Daniel"},"fr":{"text":"Le prophète Daniel"},"en":{"text":"The prophet Daniel"},"es":{"text":"El profeta Daniel"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O profeta Jeremias"},"fr":{"text":"Le prophète Jérémie"},"en":{"text":"The prophet Jeremias"},"es":{"text":"El profeta Jeremías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-easy-012","type":"choice","level":"easy","testament":"nt","book":"REV","chapter":1,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Em que ilha estava João quando teve as visões do Apocalipse?","bible_ref":"Apocalipse 1:9","verse_text":"Eu, João, (que também sou vosso irmão, e companheiro na aflição, e no Reino, e na paciência de Jesus Cristo), estava na ilha chamada Patmos, por causa da palavra de Deus, e por causa do testemunho de Jesus Cristo."},"fr":{"prompt":"Dans quelle île Jean se trouvait-il quand il eut les visions de l’Apocalypse ?","bible_ref":"Apocalypse 1:9","verse_text":"Moi Jean, votre frère, et qui ai part avec vous à la tribulation et au royaume et à la persévérance en Jésus, j’étais dans l’île appelée Patmos, à cause de la parole de Dieu et du témoignage de Jésus."},"en":{"prompt":"On which island was John when he had the visions of Revelation?","bible_ref":"Revelation 1:9","verse_text":"I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ."},"es":{"prompt":"¿En qué isla estaba Juan cuando tuvo las visiones del Apocalipsis?","bible_ref":"Apocalipsis 1:9","verse_text":"Yo Juan, vuestro hermano, y participante en la tribulación y en el reino, y en la paciencia de Jesucristo, estaba en la isla que es llamada Patmos, por la palabra de Dios y el testimonio de Jesucristo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Patmos"},"fr":{"text":"Patmos"},"en":{"text":"Patmos"},"es":{"text":"Patmos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Chipre"},"fr":{"text":"Chypre"},"en":{"text":"Cyprus"},"es":{"text":"Cipro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Creta"},"fr":{"text":"Crète"},"en":{"text":"Crete"},"es":{"text":"Creta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Malta"