select public.upsert_bank_question($json${"id":"apos-medium-006","type":"choice","level":"medium","testament":"nt","book":"ACT","chapter":11,"verse_start":26,"verse_end":26,"texts":{"pt":{"prompt":"Em que cidade os discípulos foram chamados cristãos pela primeira vez?","bible_ref":"Atos 11:26","verse_text":"E sucedeu que, durante um ano completo eles se congregaram naquela igreja, e ensinavam a uma grande multidão; e em Antioquia os discípulos foram chamados pela primeira vez de cristãos."},"fr":{"prompt":"Dans quelle ville les disciples furent-ils appelés chrétiens pour la première fois ?","bible_ref":"Actes 11:26","verse_text":"et, l’ayant trouvé, il l’amena à Antioche. Pendant toute une année, ils se réunirent aux assemblées de l’Église, et ils enseignèrent beaucoup de personnes. Ce fut à Antioche que, pour la première fois, les disciples furent appelés chrétiens."},"en":{"prompt":"In which city were the disciples first called Christians?","bible_ref":"Acts 11:26","verse_text":"And when he had found him, he brought him unto Antioch. And it came to pass, that a whole year they assembled themselves with the church, and taught much people. And the disciples were called Christians first in Antioch."},"es":{"prompt":"¿En qué ciudad los discípulos fueron llamados cristianos por primera vez?","bible_ref":"Hechos 11:26","verse_text":"Y conversaron todo un año allí con la iglesia, y enseñaron á mucha gente; y los discípulos fueron llamados Cristianos primeramente en Antioquía."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Antioquia"},"fr":{"text":"Antioche"},"en":{"text":"Antioch"},"es":{"text":"Antioquía"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jerusalém"},"fr":{"text":"Jérusalem"},"en":{"text":"Jerusalem"},"es":{"text":"Jerusalem"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Roma"},"fr":{"text":"Rome"},"en":{"text":"Rome"},"es":{"text":"Roma"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Damasco"},"fr"