select public.upsert_bank_question($json${"id":"apos-medium-007","type":"choice","level":"medium","testament":"nt","book":"ACT","chapter":16,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"O que vendia Lídia, da cidade de Tiatira?","bible_ref":"Atos 16:14","verse_text":"E uma certa mulher, por nome Lídia, vendedora de púrpura, da cidade de Tiatira, que servia a Deus; ela nos ouviu; o coração da qual o Senhor abriu, para que prestasse atenção ao que Paulo dizia."},"fr":{"prompt":"Que vendait Lydie, de la ville de Thyatire ?","bible_ref":"Actes 16:14","verse_text":"L’une d’elles, nommée Lydie, marchande de pourpre, de la ville de Thyatire, était une femme craignant Dieu, et elle écoutait. Le Seigneur lui ouvrit le cœur, pour qu’elle fût attentive à ce que disait Paul."},"en":{"prompt":"What did Lydia, of the city of Thyatira, sell?","bible_ref":"Acts 16:14","verse_text":"And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."},"es":{"prompt":"¿Qué vendía Lidia, de la ciudad de Tiatira?","bible_ref":"Hechos 16:14","verse_text":"Entonces una mujer llamada Lidia, que vendía púrpura en la ciudad de Tiatira, temerosa de Dios, estaba oyendo; el corazón de la cual abrió el Señor para que estuviese atenta á lo que Pablo decía."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Púrpura"},"fr":{"text":"De la pourpre"},"en":{"text":"Purple"},"es":{"text":"Púrpura"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Azeite"},"fr":{"text":"De l’huile"},"en":{"text":"Oil"},"es":{"text":"Aceite"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Perfume"},"fr":{"text":"Du parfum"},"en":{"text":"Perfume"},"es":{"text":"Perfume"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Linho"},"fr":{"text":"Du lin"},"en":{"text":"Linen"},"es":{"text":"Lino"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-medium-008","type":"choice","level":"medium","testament":"nt","book":"2TH","chapter":3,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Aos tessalonicenses: se alguém não quiser trabalhar, o que também não deve fazer?","bible_ref":"2 Tessalonicenses 3:10","verse_text":"Porque, quando ainda estávamos convosco, isto vos mandamos: que se alguém não quiser trabalhar, também não coma."},"fr":{"prompt":"Aux Thessaloniciens : si quelqu’un ne veut pas travailler, que ne doit-il pas faire non plus ?","bible_ref":"2 Thessaloniciens 3:10","verse_text":"Car, lorsque nous étions chez vous, nous vous disions expressément: Si quelqu’un ne veut pas travailler, qu’il ne mange pas non plus."},"en":{"prompt":"To the Thessalonians: if any would not work, what should he not do either?","bible_ref":"2 Thessalonians 3:10","verse_text":"For even when we were with you, this we commanded you, that if any would not work, neither should he eat."},"es":{"prompt":"A los tesalonicenses: si alguno no quisiere trabajar, ¿qué tampoco debe hacer?","bible_ref":"2 Tesalonicenses 3:10","verse_text":"Porque aun estando con vosotros, os denunciábamos esto: Que si alguno no quisiere trabajar, tampoco coma."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Comer"},"fr":{"text":"Manger"},"en":{"text":"Eat"},"es":{"text":"Comer"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Falar"},"fr":{"text":"Parler"},"en":{"text":"Speak"},"es":{"text":"Hablar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dormir"},"fr":{"text":"Dormir"},"en":{"text":"Sleep"},"es":{"text":"Dormir"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Viajar"},"fr":{"text":"Voyager"},"en":{"text":"Travel"},"es":{"text":"Viajar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-medium-009","type":"choice","level":"medium","testament":"nt","book":"1CO","chapter":13,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Em 1 Coríntios 13:13, qual é a maior das três coisas que permanecem?","bible_ref":"1 Coríntios 13:13","verse_text":"E agora continuam a fé, a esperança, e o amor, estes três; porém o maior destes é o amor."},"fr":{"prompt":"En 1 Corinthiens 13:13, quelle est la plus grande des trois choses qui demeurent ?","bible_ref":"1 Corinthiens 13:13","verse_text":"Maintenant donc ces trois choses demeurent: la foi, l’espérance, la charité; mais la plus grande de ces choses, c’est la charité."},"en":{"prompt":"In 1 Corinthians 13:13, which is the greatest of the three things that abide?","bible_ref":"1 Corinthians 13:13","verse_text":"And now abideth faith, hope, charity, these three; but the greatest of these is charity."},"es":{"prompt":"En 1 Corintios 13:13, ¿cuál es la mayor de las tres cosas que permanecen?","bible_ref":"1 Corintios 13:13","verse_text":"Y ahora permanecen la fe, la esperanza, y la caridad, estas tres: empero la mayor de ellas es la caridad."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O amor"},"fr":{"text":"La charité"},"en":{"text":"Charity"},"es":{"text":"La caridad"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A fé"},"fr":{"text":"La foi"},"en":{"text":"Faith"},"es":{"text":"La fe"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A esperança"},"fr":{"text":"L’espérance"},"en":{"text":"Hope"},"es":{"text":"La esperanza"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A paciência"},"fr":{"text":"La patience"},"en":{"text":"Patience"},"es":{"text":"La paciencia"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-medium-010","type":"choice","level":"medium","testament":"nt","book":"GAL","chapter":5,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Qual destas coisas faz parte do fruto do Espírito?","bible_ref":"Gálatas 5:22","verse_text":"Mas o fruto do Espírito é: amor, alegria, paz, paciência, benignidade, bondade, fidelidade,"},"fr":{"prompt":"Laquelle de ces choses fait partie du fruit de l’Esprit ?","bible_ref":"Galates 5:22","verse_text":"Mais le fruit de l’Esprit, c’est l’amour, la joie, la paix, la patience, la bonté, la bénignité, la fidélité, la douceur, la tempérance;"},"en":{"prompt":"Which of these is part of the fruit of the Spirit?","bible_ref":"Galatians 5:22","verse_text":"But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,"},"es":{"prompt":"¿Cuál de estas cosas forma parte del fruto del Espíritu?","bible_ref":"Gálatas 5:22","verse_text":"Mas el fruto del Espíritu es: caridad, gozo, paz, tolerancia, benignidad, bondad, fe,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Alegria"},"fr":{"text":"La joie"},"en":{"text":"Joy"},"es":{"text":"Gozo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Riqueza"},"fr":{"text":"La richesse"},"en":{"text":"Riches"},"es":{"text":"Riqueza"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Força"},"fr":{"text":"La force"},"en":{"text":"Strength"},"es":{"text":"Fuerza"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sabedoria"},"fr":{"text":"La sagesse"},"en":{"text":"Wisdom"},"es":{"text":"Sabiduría"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-medium-011","type":"choice","level":"medium","testament":"nt","book":"REV","chapter":1,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"A quantas igrejas devia João enviar o livro do que via?","bible_ref":"Apocalipse 1:11","verse_text":"Dizendo: “Eu sou o Alfa e o Ômega, o primeiro e o último; e o que tu estás vendo, escreve em um livro, e envia às sete igrejas que estão na Ásia: a Éfeso, e a Esmirna, e a Pérgamo, e a Tiatira, e a Sardes, e a Filadélfia, e a Laodiceia”."},"fr":{"prompt":"À combien d’Églises Jean devait-il envoyer le livre de ce qu’il voyait ?","bible_ref":"Apocalypse 1:11","verse_text":"qui disait: Ce que tu vois, écris-le dans un livre, et envoie-le aux sept Églises, à Éphèse, à Smyrne, à Pergame, à Thyatire, à Sardes, à Philadelphie, et à Laodicée."},"en":{"prompt":"To how many churches was John to send the book of what he saw?","bible_ref":"Revelation 1:11","verse_text":"Saying, I am Alpha and Omega, the first and the last: and, What thou seest, write in a book, and send it unto the seven churches which are in Asia; unto Ephesus, and unto Smyrna, and unto Pergamos, and unto Thyatira, and unto Sardis, and unto Philadelphia, and unto Laodicea."},"es":{"prompt":"¿A cuántas iglesias debía Juan enviar el libro de lo que veía?","bible_ref":"Apocalipsis 1:11","verse_text":"Que decía: Yo soy el Alpha y Omega, el primero y el último. Escribe en un libro lo que ves, y envíalo á las siete iglesias que están en Asia; á Efeso, y á Smirna, y á Pérgamo, y á Tiatira, y á Sardis, y á Filadelfia, y á Laodicea."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dez"},"fr":{"text":"Dix"},"en":{"text":"Ten"},"es":{"text":"Diez"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-medium-012","type":"choice","level":"medium","testament":"nt","book":"EPH","chapter":6,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Na armadura de Deus, o que é a espada do Espírito?","bible_ref":"Efésios 6:17","verse_text":"Pegai também o capacete da salvação, e a espada do Espírito, que é a palavra de Deus;"},"fr":{"prompt":"Dans les armes de Dieu, qu’est-ce que l’épée de l’Esprit ?","bible_ref":"Éphésiens 6:17","verse_text":"prenez aussi le casque du salut, et l’épée de l’Esprit, qui est la parole de Dieu."},"en":{"prompt":"In the armour of God, what is the sword of the Spirit?","bible_ref":"Ephesians 6:17","verse_text":"And take the helmet of salvation, and the sword of the Spirit, which is the word of God:"},"es":{"prompt":"En la armadura de Dios, ¿qué es la espada del Espíritu?","bible_ref":"Efesios 6:17","verse_text":"Y tomad el yelmo de salud, y la espada del Espíritu; que es la palabra de Dios;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A palavra de Deus"},"fr":{"text":"La parole de Dieu"},"en":{"text":"The word of God"},"es":{"text":"La palabra de Dios"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A fé"},"fr":{"text":"La foi"},"en":{"text":"Faith"},"es":{"text":"La fe"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A oração"},"fr":{"text":"La prière"},"en":{"text":"Prayer"},"es":{"text":"La oración"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A verdade"},"fr":{"text":"La vérité"},"en":{"text":"Truth"},"es":{"text":"La verdad"}}}]}$json$::jsonb);
