select public.upsert_bank_question($json${"id":"apos-medium-017","type":"verse","level":"medium","testament":"nt","book":"HEB","chapter":11,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Ora, a _____ é a certeza das coisas que se esperam, e a prova das coisas que não se veem.","bible_ref":"Hebreus 11:1","verse_text":"Ora, a fé é a certeza das coisas que se esperam, e a prova das coisas que não se veem."},"fr":{"prompt":"Or la _____ est une ferme assurance des choses qu’on espère, une démonstration de celles qu’on ne voit pas.","bible_ref":"Hébreux 11:1","verse_text":"Or la foi est une ferme assurance des choses qu’on espère, une démonstration de celles qu’on ne voit pas."},"en":{"prompt":"Now _____ is the substance of things hoped for, the evidence of things not seen.","bible_ref":"Hebrews 11:1","verse_text":"Now faith is the substance of things hoped for, the evidence of things not seen."},"es":{"prompt":"Es pues la _____ la sustancia de las cosas que se esperan, la demostración de las cosas que no se ven.","bible_ref":"Hebreos 11:1","verse_text":"Es pues la fe la sustancia de las cosas que se esperan, la demostración de las cosas que no se ven."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"graça"},"fr":{"text":"grâce"},"en":{"text":"grace"},"es":{"text":"gracia"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"fé"},"fr":{"text":"foi"},"en":{"text":"faith"},"es":{"text":"fe"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"lei"},"fr":{"text":"loi"},"en":{"text":"law"},"es":{"text":"ley"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"paz"},"fr":{"text":"paix"},"en":{"text":"peace"},"es":{"text":"paz"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-medium-018","type":"verse","level":"medium","testament":"nt","book":"ROM","chapter":6,"verse_start":23,"verse_end":23,"texts":{"pt":{"prompt":"porque o salário do pecado é a _____, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus nosso Senhor.","bible_ref":"Romanos 6:23","verse_text":"porque o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus nosso Senhor."},"fr":{"prompt":"Car le salaire du péché, c’est la _____; mais le don gratuit de Dieu, c’est la vie éternelle en Jésus-Christ notre Seigneur.","bible_ref":"Romains 6:23","verse_text":"Car le salaire du péché, c’est la mort; mais le don gratuit de Dieu, c’est la vie éternelle en Jésus-Christ notre Seigneur."},"en":{"prompt":"For the wages of sin is _____; but the gift of God is eternal life through Jesus Christ our Lord.","bible_ref":"Romans 6:23","verse_text":"For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord."},"es":{"prompt":"Porque la paga del pecado es _____: mas la dádiva de Dios es vida eterna en Cristo Jesús Señor nuestro.","bible_ref":"Romanos 6:23","verse_text":"Porque la paga del pecado es muerte: mas la dádiva de Dios es vida eterna en Cristo Jesús Señor nuestro."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"dor"},"fr":{"text":"douleur"},"en":{"text":"pain"},"es":{"text":"dolor"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"vergonha"},"fr":{"text":"honte"},"en":{"text":"shame"},"es":{"text":"vergüenza"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"tristeza"},"fr":{"text":"tristesse"},"en":{"text":"sorrow"},"es":{"text":"tristeza"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"morte"},"fr":{"text":"mort"},"en":{"text":"death"},"es":{"text":"muerte"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-medium-019","type":"verse","level":"medium","testament":"nt","book":"JAS","chapter":1,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"e sede praticantes da _____, e não somente ouvintes, enganando a vós mesmos.","bible_ref":"Tiago 1:22","verse_text":"e sede praticantes da palavra, e não somente ouvintes, enganando a vós mesmos."},"fr":{"prompt":"Mettez en pratique la _____, et ne vous bornez pas à l’écouter, en vous trompant vous-mêmes par de faux raisonnements.","bible_ref":"Jacques 1:22","verse_text":"Mettez en pratique la parole, et ne vous bornez pas à l’écouter, en vous trompant vous-mêmes par de faux raisonnements."},"en":{"prompt":"But be ye doers of the _____, and not hearers only, deceiving your own selves.","bible_ref":"James 1:22","verse_text":"But be ye doers of the word, and not hearers only, deceiving your own selves."},"es":{"prompt":"Mas sed hacedores de la _____, y no tan solamente oidores, engañándoos á vosotros mismos.","bible_ref":"Santiago 1:22","verse_text":"Mas sed hacedores de la palabra, y no tan solamente oidores, engañándoos á vosotros mismos."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"oração"},"fr":{"text":"prière"},"en":{"text":"prayer"},"es":{"text":"oración"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"palavra"},"fr":{"text":"parole"},"en":{"text":"word"},"es":{"text":"palabra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"promessa"},"fr":{"text":"promesse"},"en":{"text":"promise"},"es":{"text":"promesa"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"verdade"},"fr":{"text":"vérité"},"en":{"text":"truth"},"es":{"text":"verdad"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-medium-020","type":"verse","level":"medium","testament":"nt","book":"1TI","chapter":6,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Pois o amor ao _____ é raiz de todos os tipos de males. Alguns o cobiçam, e então se desviaram da fé, e perfuraram a si mesmos com muitas dores.","bible_ref":"1 Timóteo 6:10","verse_text":"Pois o amor ao dinheiro é raiz de todos os tipos de males. Alguns o cobiçam, e então se desviaram da fé, e perfuraram a si mesmos com muitas dores."},"fr":{"prompt":"Car l’amour de l’_____ est une racine de tous les maux; et quelques-uns, en étant possédés, se sont égarés loin de la foi, et se sont jetés eux-mêmes dans bien des tourments.","bible_ref":"1 Timothée 6:10","verse_text":"Car l’amour de l’argent est une racine de tous les maux; et quelques-uns, en étant possédés, se sont égarés loin de la foi, et se sont jetés eux-mêmes dans bien des tourments."},"en":{"prompt":"For the love of _____ is the root of all evil: which while some coveted after, they have erred from the faith, and pierced themselves through with many sorrows.","bible_ref":"1 Timothy 6:10","verse_text":"For the love of money is the root of all evil: which while some coveted after, they have erred from the faith, and pierced themselves through with many sorrows."},"es":{"prompt":"Porque el amor del _____ es la raíz de todos los males: el cual codiciando algunos, se descaminaron de la fe, y fueron traspasados de muchos dolores.","bible_ref":"1 Timoteo 6:10","verse_text":"Porque el amor del dinero es la raíz de todos los males: el cual codiciando algunos, se descaminaron de la fe, y fueron traspasados de muchos dolores."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"orgulho"},"fr":{"text":"orgueil"},"en":{"text":"pride"},"es":{"text":"orgullo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"ouro"},"fr":{"text":"or"},"en":{"text":"gold"},"es":{"text":"oro"}}},{"position":3,"is_correct":fa