select public.upsert_bank_question($json${"id":"apos-hard-001","type":"choice","level":"hard","testament":"nt","book":"ACT","chapter":13,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Em Chipre, que mago se opunha a Paulo e Barnabé, procurando afastar o procônsul da fé?","bible_ref":"Atos 13:8","verse_text":"Mas resistia-lhes Elimas, o mago (que assim significa seu nome), procurando afastar o procônsul da fé."},"fr":{"prompt":"À Chypre, quel magicien s’opposait à Paul et Barnabas, cherchant à détourner le proconsul de la foi ?","bible_ref":"Actes 13:8","verse_text":"Mais Élymas, le magicien, car c’est ce que signifie son nom, leur faisait opposition, cherchant à détourner de la foi le proconsul."},"en":{"prompt":"In Cyprus, which sorcerer withstood Paul and Barnabas, seeking to turn the deputy from the faith?","bible_ref":"Acts 13:8","verse_text":"But Elymas the sorcerer (for so is his name by interpretation) withstood them, seeking to turn away the deputy from the faith."},"es":{"prompt":"En Cipro, ¿qué mago resistía a Pablo y Bernabé, procurando apartar de la fe al procónsul?","bible_ref":"Hechos 13:8","verse_text":"Mas les resistía Elimas el encantador (que así se interpreta su nombre), procurando apartar de la fe al procónsul."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Elimas"},"fr":{"text":"Élymas"},"en":{"text":"Elymas"},"es":{"text":"Elimas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Simão"},"fr":{"text":"Simon"},"en":{"text":"Simon"},"es":{"text":"Simón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Demétrio"},"fr":{"text":"Démétrius"},"en":{"text":"Demetrius"},"es":{"text":"Demetrio"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ananias"},"fr":{"text":"Ananias"},"en":{"text":"Ananias"},"es":{"text":"Ananías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-002","type":"choice","level":"hard","testament":"nt","book":"ACT","chapter":27,"verse_start":37,"verse_end":37,"texts":{"pt":{"prompt":"Quantas pessoas iam no navio de Paulo antes do naufrágio?","bible_ref":"Atos 27:37","verse_text":"E éramos todos no navio duzentas e setenta e seis almas."},"fr":{"prompt":"Combien de personnes y avait-il dans le navire de Paul avant le naufrage ?","bible_ref":"Actes 27:37","verse_text":"Nous étions, dans le navire, deux cent soixante-seize personnes en tout."},"en":{"prompt":"How many souls were in Paul’s ship before the shipwreck?","bible_ref":"Acts 27:37","verse_text":"And we were in all in the ship two hundred threescore and sixteen souls."},"es":{"prompt":"¿Cuántas personas iban en la nave de Pablo antes del naufragio?","bible_ref":"Hechos 27:37","verse_text":"Y éramos todas las personas en la nave doscientas setenta y seis."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"276"},"fr":{"text":"276"},"en":{"text":"276"},"es":{"text":"276"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"176"},"fr":{"text":"176"},"en":{"text":"176"},"es":{"text":"176"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"300"},"fr":{"text":"300"},"en":{"text":"300"},"es":{"text":"300"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"75"},"fr":{"text":"75"},"en":{"text":"75"},"es":{"text":"75"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-003","type":"choice","level":"hard","testament":"nt","book":"PHM","chapter":1,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Por quem pede Paulo a Filémon, chamando-lhe «meu filho»?","bible_ref":"Filémon 1:10","verse_text":"Eu te peço por meu filho Onésimo, ao qual eu gerei durante minhas prisões."},"fr":{"prompt":"Pour qui Paul prie-t-il Philémon, l’appelant « mon enfant » ?","bible_ref":"Philémon 1:10","verse_text":"Je te prie pour mon enfant, que j’ai engendré étant dans les chaînes, Onésime,"},"en":{"prompt":"For whom does Paul beseech Philemon, calling him “my son”?","bible_ref":"Philemon 1:10","verse_text":"I beseech thee for my son Onesimus, whom I have begotten in my bonds:"},"es":{"prompt":"¿Por quién ruega Pablo a Filemón, llamándolo «mi hijo»?","bible_ref":"Filemón 1:10","verse_text":"Ruégote por mi hijo Onésimo, que he engendrado en mis prisiones,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Onésimo"},"fr":{"text":"Onésime"},"en":{"text":"Onesimus"},"es":{"text":"Onésimo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Tíquico"},"fr":{"text":"Tychique"},"en":{"text":"Tychicus"},"es":{"text":"Tichîco"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Epafras"},"fr":{"text":"Épaphras"},"en":{"text":"Epaphras"},"es":{"text":"Epafras"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Demas"},"fr":{"text":"Démas"},"en":{"text":"Demas"},"es":{"text":"Demas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-004","type":"choice","level":"hard","testament":"nt","book":"2TI","chapter":1,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Como se chamava a avó de Timóteo, em quem habitou primeiro a fé?","bible_ref":"2 Timóteo 1:5","verse_text":"Trago à memória a fé não fingida que há em ti, fé que habitou primeiro na tua avó Loide, e na tua mãe Eunice; e tenho certeza que também em ti."},"fr":{"prompt":"Comment s’appelait l’aïeule de Timothée, en qui la foi habita d’abord ?","bible_ref":"2 Timothée 1:5","verse_text":"gardant le souvenir de la foi sincère qui est en toi, qui habita d’abord dans ton aïeule Loïs et dans ta mère Eunice, et qui, j’en suis persuadé, habite aussi en toi."},"en":{"prompt":"What was the name of Timothy’s grandmother, in whom faith dwelt first?","bible_ref":"2 Timothy 1:5","verse_text":"When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also."},"es":{"prompt":"¿Cómo se llamaba la abuela de Timoteo, en quien residió primero la fe?","bible_ref":"2 Timoteo 1:5","verse_text":"Trayendo á la memoria la fe no fingida que hay en ti, la cual residió primero en tu abuela Loida, y en tu madre Eunice; y estoy cierto que en ti también."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Loide"},"fr":{"text":"Loïs"},"en":{"text":"Lois"},"es":{"text":"Loida"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Eunice"},"fr":{"text":"Eunice"},"en":{"text":"Eunice"},"es":{"text":"Eunice"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Lídia"},"fr":{"text":"Lydie"},"en":{"text":"Lydia"},"es":{"text":"Lidia"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Priscila"},"fr":{"text":"Priscille"},"en":{"text":"Priscilla"},"es":{"text":"Priscila"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-005","type":"choice","level":"hard","testament":"nt","book":"COL","chapter":4,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Em Colossenses, como descreve Paulo a profissão de Lucas?","bible_ref":"Colossenses 4:14","verse_text":"Lucas, o médico amado, vos saúda; e também Demas."},"fr":{"prompt":"Dans Colossiens, quel métier Paul attribue-t-il à Luc ?","bible_ref":"Colossiens 4:14","verse_text":"Luc, le médecin bien-aimé, vous salue, ainsi que Démas."},"en":{"prompt":"In Colossians, what does Paul call Luke?","bible_ref":"Colossians 4:14","verse_text":"Luke, the beloved physician, and Demas, greet you."},"es":{"prompt":"En Colosenses, ¿qué oficio atribuye Pablo a Lucas?","bible_ref":"Colosenses 4:14","verse_text":"Os saluda Lucas, el médico amado, y Demas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Médico"},"fr":{"text":"Médecin"},"en":{"text":"A physician"},"es":{"text":"Médico"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Escriba"},"fr":{"text":"Scribe"},"en":{"text":"A scribe"},"es":{"text":"Escriba"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Pescador"},"fr":{"text":"Pêcheur"},"en":{"text":"A fisherman"},"es":{"text":"Pescador"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Fabricante de tendas"},"fr":{"text":"Faiseur de tentes"},"en":{"text":"A tentmaker"},"es":{"text":"Hacedor de tiendas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-006","type":"choice","level":"hard","testament":"nt","book":"TIT","chapter":1,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Em que ilha deixou Paulo Tito para pôr em ordem o que faltava?","bible_ref":"Tito 1:5","verse_text":"Por esta causa eu te deixei em Creta, para que tu continuasses a pôr em ordem as coisas que estavam faltando, e de cidade em cidade constituísses presbíteros, conforme eu te mandei."},"fr":{"prompt":"Dans quelle île Paul laissa-t-il Tite pour mettre en ordre ce qui restait à régler ?","bible_ref":"Tite 1:5","verse_text":"Je t’ai laissé en Crète, afin que tu mettes en ordre ce qui reste à régler, et que, selon mes instructions, tu établisses des anciens dans chaque ville,"},"en":{"prompt":"On which island did Paul leave Titus to set in order the things that were wanting?","bible_ref":"Titus 1:5","verse_text":"For this cause left I thee in Crete, that thou shouldest set in order the things that are wanting, and ordain elders in every city, as I had appointed thee:"},"es":{"prompt":"¿En qué isla dejó Pablo a Tito para corregir lo que faltaba?","bible_ref":"Tito 1:5","verse_text":"Por esta causa te dejé en Creta, para que corrigieses lo que falta, y pusieses ancianos por las villas, así como yo te mandé:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Creta"},"fr":{"text":"Crète"},"en":{"text":"Crete"},"es":{"text":"Creta"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Chipre"},"fr":{"text":"Chypre"},"en":{"text":"Cyprus"},"es":{"text":"Cipro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Rodes"},"fr":{"text":"Rhodes"},"en":{"text":"Rhodes"},"es":{"text":"Rhodas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Malta"},"fr":{"text":"Malte"},"en":{"text":"Melita"},"es":{"text":"Melita"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-007","type":"choice","level":"hard","testament":"nt","book":"3JN","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"A quem é dirigida a Terceira Epístola de João?","bible_ref":"3 João 1:1","verse_text":"O ancião, ao amado Gaio, a quem amo em verdade."},"fr":{"prompt":"À qui la troisième épître de Jean est-elle adressée ?","bible_ref":"3 Jean 1:1","verse_text":"L’ancien, à Gaïus, le bien-aimé, que j’aime dans la vérité."},"en":{"prompt":"To whom is the Third Epistle of John addressed?","bible_ref":"3 John 1:1","verse_text":"The elder unto the wellbeloved Gaius, whom I love in the truth."},"es":{"prompt":"¿A quién va dirigida la tercera epístola de Juan?","bible_ref":"3 Juan 1:1","verse_text":"El anciano al muy amado Gaio, al cual yo amo en verdad."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Gaio"},"fr":{"text":"Gaïus"},"en":{"text":"Gaius"},"es":{"text":"Gaio"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Diótrefes"},"fr":{"text":"Diotrèphe"},"en":{"text":"Diotrephes"},"es":{"text":"Diótrefes"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Demétrio"},"fr":{"text":"Démétrius"},"en":{"text":"Demetrius"},"es":{"text":"Demetrio"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tíquico"},"fr":{"text":"Tychique"},"en":{"text":"Tychicus"},"es":{"text":"Tichîco"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-008","type":"choice","level":"hard","testament":"nt","book":"JUD","chapter":1,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Segundo Judas, por causa do corpo de quem disputou o arcanjo Miguel com o diabo?","bible_ref":"Judas 1:9","verse_text":"Mas Miguel, o arcanjo, quando ele discutia com o diabo, e disputava por causa do corpo de Moisés, não ousou contra ele pronunciar juízo de maldição, porém disse: “O Senhor te repreenda.”"},"fr":{"prompt":"Selon Jude, l’archange Michel disputa au diable le corps de qui ?","bible_ref":"Jude 1:9","verse_text":"Or, l’archange Michel, lorsqu’il contestait avec le diable et lui disputait le corps de Moïse, n’osa pas porter contre lui un jugement injurieux, mais il dit: Que le Seigneur te réprime!"},"en":{"prompt":"According to Jude, about whose body did Michael the archangel dispute with the devil?","bible_ref":"Jude 1:9","verse_text":"Yet Michael the archangel, when contending with the devil he disputed about the body of Moses, durst not bring against him a railing accusation, but said, The Lord rebuke thee."},"es":{"prompt":"Según Judas, ¿por el cuerpo de quién disputó el arcángel Miguel con el diablo?","bible_ref":"Judas 1:9","verse_text":"Pero cuando el arcángel Miguel contendía con el diablo, disputando sobre el cuerpo de Moisés, no se atrevió á usar de juicio de maldición contra él, sino que dijo: El Señor te reprenda."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Elias"},"fr":{"text":"Élie"},"en":{"text":"Elias"},"es":{"text":"Elías"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Abraão"},"fr":{"text":"Abraham"},"en":{"text":"Abraham"},"es":{"text":"Abraham"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Enoque"},"fr":{"text":"Énoch"},"en":{"text":"Enoch"},"es":{"text":"Enoc"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-009","type":"choice","level":"hard","testament":"nt","book":"REV","chapter":3,"verse_start":14,"verse_end":15,"texts":{"pt":{"prompt":"A que igreja diz o Senhor: «tu nem és frio nem quente»?","bible_ref":"Apocalipse 3:14-15","verse_text":"“E escreve ao anjo da igreja dos laodicenses: “Isto diz o Amém, a testemunha fiel e verdadeira, o principal da criação de Deus: “Eu conheço as tuas obras, que tu nem és frio, nem quente; melhor seria que tu fosses frio ou quente!"},"fr":{"prompt":"À quelle Église le Seigneur dit-il : « tu n’es ni froid ni bouillant » ?","bible_ref":"Apocalypse 3:14-15","verse_text":"Écris à l’ange de l’Église de Laodicée: Voici ce que dit l’Amen, le témoin fidèle et véritable, le commencement de la création de Dieu: Je connais tes œuvres. Je sais que tu n’es ni froid ni bouillant. Puisses-tu être froid ou bouillant!"},"en":{"prompt":"To which church does the Lord say “thou art neither cold nor hot”?","bible_ref":"Revelation 3:14-15","verse_text":"And unto the angel of the church of the Laodiceans write; These things saith the Amen, the faithful and true witness, the beginning of the creation of God; I know thy works, that thou art neither cold nor hot: I would thou wert cold or hot."},"es":{"prompt":"¿A qué iglesia dice el Señor: «ni eres frío ni caliente»?","bible_ref":"Apocalipsis 3:14-15","verse_text":"Y escribe al ángel de la iglesia en LAODICEA: He aquí dice el Amén, el testigo fiel y verdadero, el principio de la creación de Dios: Yo conozco tus obras, que ni eres frío, ni caliente. ¡Ojalá fueses frío, ó caliente!"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Laodiceia"},"fr":{"text":"Laodicée"},"en":{"text":"Laodicea"},"es":{"text":"Laodicea"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sardes"},"fr":{"text":"Sardes"},"en":{"text":"Sardis"},"es":{"text":"Sardis"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Éfeso"},"fr":{"text":"Éphèse"},"en":{"text":"Ephesus"},"es":{"text":"Efeso"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Esmirna"},"fr":{"text":"Smyrne"},"en":{"text":"Smyrna"},"es":{"text":"Smirna"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-010","type":"choice","level":"hard","testament":"nt","book":"2PE","chapter":3,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Segundo Pedro, para o Senhor um dia é como quanto tempo?","bible_ref":"2 Pedro 3:8","verse_text":"Mas amados, desta uma coisa não ignoreis: que um dia para o Senhor é como mil anos, e mil anos como um dia."},"fr":{"prompt":"Selon Pierre, devant le Seigneur, un jour est comme combien de temps ?","bible_ref":"2 Pierre 3:8","verse_text":"Mais il est une chose, bien-aimés, que vous ne devez pas ignorer, c’est que, devant le Seigneur, un jour est comme mille ans, et mille ans sont comme un jour."},"en":{"prompt":"According to Peter, one day is with the Lord as how long?","bible_ref":"2 Peter 3:8","verse_text":"But, beloved, be not ignorant of this one thing, that one day is with the Lord as a thousand years, and a thousand years as one day."},"es":{"prompt":"Según Pedro, ¿cuánto tiempo es un día delante del Señor?","bible_ref":"2 Pedro 3:8","verse_text":"Mas, oh amados, no ignoréis esta una cosa: que un día delante del Señor es como mil años y mil años como un día."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Mil anos"},"fr":{"text":"Mille ans"},"en":{"text":"A thousand years"},"es":{"text":"Mil años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Cem anos"},"fr":{"text":"Cent ans"},"en":{"text":"A hundred years"},"es":{"text":"Cien años"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quarenta anos"},"fr":{"text":"Quarante ans"},"en":{"text":"Forty years"},"es":{"text":"Cuarenta años"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sete anos"},"fr":{"text":"Sept ans"},"en":{"text":"Seven years"},"es":{"text":"Siete años"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-011","type":"choice","level":"hard","testament":"nt","book":"2JN","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Na Segunda Epístola de João, que palavra usa o ancião para descrever a senhora a quem escreve?","bible_ref":"2 João 1:1","verse_text":"O ancião, à senhora eleita, e a seus filhos, aos quais eu amo em verdade; e não somente eu, mas também todos os que têm conhecido a verdade;"},"fr":{"prompt":"Dans la deuxième épître de Jean, quel mot l’ancien emploie-t-il pour la dame à qui il écrit ?","bible_ref":"2 Jean 1:1","verse_text":"L’ancien, à Kyria l’élue et à ses enfants, que j’aime dans la vérité, et ce n’est pas moi seul qui les aime, mais aussi tous ceux qui ont connu la vérité,"},"en":{"prompt":"In the Second Epistle of John, what word does the elder use for the lady he writes to?","bible_ref":"2 John 1:1","verse_text":"The elder unto the elect lady and her children, whom I love in the truth; and not I only, but also all they that have known the truth;"},"es":{"prompt":"En la segunda epístola de Juan, ¿qué palabra usa el anciano para la señora a quien escribe?","bible_ref":"2 Juan 1:1","verse_text":"El anciano á la señora elegida y á sus hijos, á los cuales yo amo en verdad; y no yo solo, sino también todos los que han conocido la verdad,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Eleita"},"fr":{"text":"Élue"},"en":{"text":"Elect"},"es":{"text":"Elegida"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Viúva"},"fr":{"text":"Veuve"},"en":{"text":"Widowed"},"es":{"text":"Viuda"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Rica"},"fr":{"text":"Riche"},"en":{"text":"Rich"},"es":{"text":"Rica"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Idosa"},"fr":{"text":"Âgée"},"en":{"text":"Aged"},"es":{"text":"Anciana"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"apos-hard-012","type":"choice","level":"hard","testament":"nt","book":"2CO","chapter":11,"verse_start":25,"verse_end":25,"texts":{"pt":{"prompt":"Quantas vezes diz Paulo que sofreu naufrágio?","bible_ref":"2 Coríntios 11:25","verse_text":"Por três vezes já fui espancado com varas, uma vez fui apedrejado, três vezes sofri naufrágios, passei uma noite e um dia à deriva no mar profundo;"},"fr":{"prompt":"Combien de fois Paul dit-il avoir fait naufrage ?","bible_ref":"2 Corinthiens 11:25","verse_text":"trois fois j’ai été battu de verges, une fois j’ai été lapidé, trois fois j’ai fait naufrage, j’ai passé un jour et une nuit dans l’abîme."},"en":{"prompt":"How many times does Paul say he suffered shipwreck?","bible_ref":"2 Corinthians 11:25","verse_text":"Thrice was I beaten with rods, once was I stoned, thrice I suffered shipwreck, a night and a day I have been in the deep;"},"es":{"prompt":"¿Cuántas veces dice Pablo que padeció naufragio?","bible_ref":"2 Corintios 11:25","verse_text":"Tres veces he sido azotado con varas; una vez apedreado; tres veces he padecido naufragio; una noche y un día he estado en lo profundo de la mar;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Três vezes"},"fr":{"text":"Trois fois"},"en":{"text":"Three times"},"es":{"text":"Tres veces"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma vez"},"fr":{"text":"Une fois"},"en":{"text":"Once"},"es":{"text":"Una vez"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Duas vezes"},"fr":{"text":"Deux fois"},"en":{"text":"Twice"},"es":{"text":"Dos veces"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sete vezes"},"fr":{"text":"Sept fois"},"en":{"text":"Seven times"},"es":{"text":"Siete veces"}}}]}$json$::jsonb);
