select public.upsert_bank_question($json${"id":"apos-hard-017","type":"verse","level":"hard","testament":"nt","book":"2JN","chapter":1,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Eu tenho muitas coisas para vos escrever, porém não quis fazê-lo com papel e _____; mas espero vir até vós, e falar convosco face a face, para que a nossa alegria seja completa.","bible_ref":"2 João 1:12","verse_text":"Eu tenho muitas coisas para vos escrever, porém não quis fazê-lo com papel e tinta; mas espero vir até vós, e falar convosco face a face, para que a nossa alegria seja completa."},"fr":{"prompt":"Quoique j’eusse beaucoup de choses à vous écrire, je n’ai pas voulu le faire avec le papier et l’_____; mais j’espère aller chez vous, et vous parler bouche à bouche, afin que notre joie soit parfaite.","bible_ref":"2 Jean 1:12","verse_text":"Quoique j’eusse beaucoup de choses à vous écrire, je n’ai pas voulu le faire avec le papier et l’encre; mais j’espère aller chez vous, et vous parler bouche à bouche, afin que notre joie soit parfaite."},"en":{"prompt":"Having many things to write unto you, I would not write with paper and _____: but I trust to come unto you, and speak face to face, that our joy may be full.","bible_ref":"2 John 1:12","verse_text":"Having many things to write unto you, I would not write with paper and ink: but I trust to come unto you, and speak face to face, that our joy may be full."},"es":{"prompt":"Aunque tengo muchas cosas que escribiros, no he querido comunicarlas por medio de papel y _____; mas espero ir á vosotros, y hablar boca á boca, para que nuestro gozo sea cumplido.","bible_ref":"2 Juan 1:12","verse_text":"Aunque tengo muchas cosas que escribiros, no he querido comunicarlas por medio de papel y tinta; mas espero ir á vosotros, y hablar boca á boca, para que nuestro gozo sea cumplido."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"barro"},"fr":{"text":"argile"},"en":{"text":"clay"},"es":{"text":"barro"}}},{"positi