select public.upsert_bank_question($json${"id":"apos-hard-018","type":"verse","level":"hard","testament":"nt","book":"2TI","chapter":4,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Quando vieres, traz a _____ que deixei em Trôade na casa de Carpo, e os livros, principalmente os pergaminhos.","bible_ref":"2 Timóteo 4:13","verse_text":"Quando vieres, traz a capa que deixei em Trôade na casa de Carpo, e os livros, principalmente os pergaminhos."},"fr":{"prompt":"Quand tu viendras, apporte le _____ que j’ai laissé à Troas chez Carpus, et les livres, surtout les parchemins.","bible_ref":"2 Timothée 4:13","verse_text":"Quand tu viendras, apporte le manteau que j’ai laissé à Troas chez Carpus, et les livres, surtout les parchemins."},"en":{"prompt":"The _____ that I left at Troas with Carpus, when thou comest, bring with thee, and the books, but especially the parchments.","bible_ref":"2 Timothy 4:13","verse_text":"The cloke that I left at Troas with Carpus, when thou comest, bring with thee, and the books, but especially the parchments."},"es":{"prompt":"Trae, cuando vinieres, el _____ que dejé en Troas en casa de Carpo: y los libros, mayormente los pergaminos.","bible_ref":"2 Timoteo 4:13","verse_text":"Trae, cuando vinieres, el capote que dejé en Troas en casa de Carpo: y los libros, mayormente los pergaminos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"capa"},"fr":{"text":"manteau"},"en":{"text":"cloke"},"es":{"text":"capote"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"taça"},"fr":{"text":"calice"},"en":{"text":"cup"},"es":{"text":"cáliz"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"bengala"},"fr":{"text":"bâton"},"en":{"text":"staff"},"es":{"text":"bastón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"bolsa"},"fr":{"text":"sac"},"en":{"text":"bag"},"es":{"text":"saco"}}}]}$json$::jsonb);
