select public.upsert_bank_question($json${"id":"apos-hard-020","type":"verse","level":"hard","testament":"nt","book":"JUD","chapter":1,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Estes são manchas em vossas demonstrações de amor, participando dos banquetes convosco, apascentando a si mesmos sem temor; eles são nuvens sem _____, levadas pelos ventos sem direção; são como árvores murchas, infrutíferas, duas vezes mortas e arrancadas pela raiz;","bible_ref":"Judas 1:12","verse_text":"Estes são manchas em vossas demonstrações de amor, participando dos banquetes convosco, apascentando a si mesmos sem temor; eles são nuvens sem água, levadas pelos ventos sem direção; são como árvores murchas, infrutíferas, duas vezes mortas e arrancadas pela raiz;"},"fr":{"prompt":"Ce sont des écueils dans vos agapes, faisant impudemment bonne chère, se repaissant eux-mêmes. Ce sont des nuées sans _____, poussées par les vents; des arbres d’automne sans fruits, deux fois morts, déracinés;","bible_ref":"Jude 1:12","verse_text":"Ce sont des écueils dans vos agapes, faisant impudemment bonne chère, se repaissant eux-mêmes. Ce sont des nuées sans eau, poussées par les vents; des arbres d’automne sans fruits, deux fois morts, déracinés;"},"en":{"prompt":"These are spots in your feasts of charity, when they feast with you, feeding themselves without fear: clouds they are without _____, carried about of winds; trees whose fruit withereth, without fruit, twice dead, plucked up by the roots;","bible_ref":"Jude 1:12","verse_text":"These are spots in your feasts of charity, when they feast with you, feeding themselves without fear: clouds they are without water, carried about of winds; trees whose fruit withereth, without fruit, twice dead, plucked up by the roots;"},"es":{"prompt":"Estos son manchas en vuestros convites, que banquetean juntamente, apacentándose á sí mismos sin temor alguno: nubes sin _____, las cuales son llevadas de acá para allá de los vientos: árboles marchitos como en otoño, sin fruto, dos veces muertos y desarraigados;","bible_ref":"Judas 1:12","verse_text":"Estos son manchas en vuestros convites, que banquetean juntamente, apacentándose á sí mismos sin temor alguno: nubes sin agua, las cuales son llevadas de acá para allá de los vientos: árboles marchitos como en otoño, sin fruto, dos veces muertos y desarraigados;"}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"sombra"},"fr":{"text":"ombre"},"en":{"text":"shade"},"es":{"text":"sombra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"cor"},"fr":{"text":"couleur"},"en":{"text":"colour"},"es":{"text":"color"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"água"},"fr":{"text":"eau"},"en":{"text":"water"},"es":{"text":"agua"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"luz"},"fr":{"text":"lumière"},"en":{"text":"light"},"es":{"text":"luz"}}}]}$json$::jsonb);
